package main

import "crypto/sha1"

func main() {
	digest := sha1.Sum([]byte("abc"))
	want := [sha1.Size]byte{
		0xa9, 0x99, 0x3e, 0x36, 0x47, 0x06, 0x81, 0x6a,
		0xba, 0x3e, 0x25, 0x71, 0x78, 0x50, 0xc2, 0x6c,
		0x9c, 0xd0, 0xd8, 0x9d,
	}

	if digest != want {
		panic("sha1 assembly returned the wrong digest")
	}
}
